/**
 * Turning whatever the user pasted into a video id.
 *
 * People paste a whole address far more often than a bare id, and every YouTube surface
 * spells the same video differently (watch, youtu.be, shorts, embed). Accepting only the
 * bare id would push that translation onto the user every single time.
 */

/** A YouTube video id is always 11 characters of this alphabet. */
const VIDEO_ID_PATTERN = /^[A-Za-z0-9_-]{11}$/;

/** Path shapes that carry the id as the segment right after a known prefix. */
const PATH_PREFIXES = ['/shorts/', '/embed/', '/live/', '/v/'] as const;

const YOUTUBE_HOSTS = [
  'youtube.com',
  'www.youtube.com',
  'm.youtube.com',
  'music.youtube.com',
  'youtube-nocookie.com',
  'www.youtube-nocookie.com',
] as const;

const SHORT_HOSTS = ['youtu.be', 'www.youtu.be'] as const;

function asVideoId(candidate: string | undefined | null): string | null {
  if (candidate === undefined || candidate === null) return null;
  return VIDEO_ID_PATTERN.test(candidate) ? candidate : null;
}

function firstPathSegment(pathname: string): string | null {
  const segments = pathname.split('/').filter((part) => part.length > 0);
  return segments[0] ?? null;
}

function fromPathPrefix(pathname: string): string | null {
  for (const prefix of PATH_PREFIXES) {
    if (pathname.startsWith(prefix)) {
      const rest = pathname.slice(prefix.length);
      return firstPathSegment(`/${rest}`);
    }
  }
  return null;
}

function parseUrl(text: string): URL | null {
  try {
    // A bare "youtu.be/xxx" has no scheme; assume https rather than rejecting it.
    return new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(text) ? text : `https://${text}`);
  } catch {
    return null;
  }
}

/** Playlist ids vary in length and prefix (PL…, OLAK5uy_… for a YouTube Music album). */
const PLAYLIST_ID_PATTERN = /^[A-Za-z0-9_-]{10,}$/;

/**
 * Extract a playlist id from an address that names a playlist and no single video.
 *
 * YouTube Music shares albums and playlists as `music.youtube.com/playlist?list=…`, which has
 * no video in it at all, so `parseVideoId` rightly finds nothing. An address carrying both
 * (`watch?v=…&list=…`) is about the video and is left to `parseVideoId`. Never throws.
 */
export function parsePlaylistId(text: string): string | null {
  const trimmed = text.trim();
  if (trimmed.length === 0 || parseVideoId(trimmed) !== null) return null;
  const url = parseUrl(trimmed);
  if (url === null) return null;
  if (!(YOUTUBE_HOSTS as readonly string[]).includes(url.hostname.toLowerCase())) return null;
  const list = url.searchParams.get('list');
  return list !== null && PLAYLIST_ID_PATTERN.test(list) ? list : null;
}

/**
 * Extract the video id, or null when the text does not contain one.
 * Never throws: the caller is a text box that people type into.
 */
export function parseVideoId(text: string): string | null {
  const trimmed = text.trim();
  if (trimmed.length === 0) return null;

  const bare = asVideoId(trimmed);
  if (bare !== null) return bare;

  const url = parseUrl(trimmed);
  if (url === null) return null;

  const host = url.hostname.toLowerCase();

  if ((SHORT_HOSTS as readonly string[]).includes(host)) {
    return asVideoId(firstPathSegment(url.pathname));
  }

  if (!(YOUTUBE_HOSTS as readonly string[]).includes(host)) return null;

  const fromQuery = asVideoId(url.searchParams.get('v'));
  if (fromQuery !== null) return fromQuery;

  return asVideoId(fromPathPrefix(url.pathname));
}
